	/**
	 * Default Constructor
	 */
    public TeamService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TeamEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TeamRepository.class) );
		this.validator		= applicationContext.getBean(TeamValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Team
	 */
		public Team createTeam( CreateTeamCommand command ) {

		Team entity = new Team();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTeamId( command.getTeamId() );
            entity.setName( command.getName() );
            entity.setTeamType( command.getTeamType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Team {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTeamCommand
	 * @return		Team
	 */
	public Team updateTeam( UpdateTeamCommand command ) {

		Team entity = new Team();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTeamId( command.getTeamId() );
            entity.setName( command.getName() );
            entity.setOrganization( command.getOrganization() );
            entity.setUsers( command.getUsers() );
            entity.setAccounts( command.getAccounts() );
            entity.setOpportunities( command.getOpportunities() );
            entity.setCases( command.getCases() );
            entity.setCampaigns( command.getCampaigns() );
            entity.setTeamType( command.getTeamType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Team {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTeamCommand
	 */
	public void delete( DeleteTeamCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTeamId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Team {0} ", id );

	}

	/**
	 * Method to retrieve the Team via TeamFetchOneSummary
	 * @param 	summary TeamFetchOneSummary
	 * @return 	TeamFetchOneResponse
	 */
	public Team getTeam( TeamFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TeamFetchOneSummary arg cannot be null" );

		Team entity = null;
		UUID id = summary.getTeamId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Team using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Teams
	 *
	 * @return 	List<Team>
	 */
    public List<Team> getAllTeam() {
		List<Team> list = projector.findAll( new FindAllTeamQuery() );
		return list;
	}

	/**
	 * assign Organization on Team
	 * @param		command AssignOrganizationToTeamCommand
	 */
	public void assignOrganization( AssignOrganizationToTeamCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getTeamId(), command.getAssignment());

	}

